import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.*;
import java.util.stream.Collectors;
import java.util.stream.IntStream;

public class default_t {
    static class FastReader {
        BufferedReader br;
        StringTokenizer st;
        FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }
        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }
        int nextInt() {
            return Integer.parseInt(next());
        }
    }

    public static void main(String[] args) {
        FastReader in = new FastReader();
        int n = in.nextInt();
        int B = in.nextInt();
        int[] arr = new int[n];
        for (int i = 0; i < n; i++) {
            arr[i] = in.nextInt();
        }

        int[] evenPrefix = new int[n];
        int[] oddPrefix = new int[n];
        int even = 0;
        int odd = 0;
        for (int i = 0; i < n; i++) {
            if ((arr[i] & 1) == 0) {
                even++;
            } else {
                odd++;
            }
            evenPrefix[i] = even;
            oddPrefix[i] = odd;
        }

        List<Integer> costs = IntStream.range(0, n - 1)
                .filter(i -> evenPrefix[i] == oddPrefix[i])
                .map(i -> Math.abs(arr[i] - arr[i + 1]))
                .boxed()
                .collect(Collectors.toList());

        Collections.sort(costs);
        int budget = B;
        long ans = 0;
        if (budget >= 0) {
            for (int c : costs) {
                budget -= c;
                if (budget < 0) {
                    break;
                }
                ans++;
            }
        }
        System.out.println(ans);
    }
}
